//
// GENERATED RSA-PSS verify corpus. Real signatures produced by the system
// openssl (LibreSSL) with rsa_padding_mode:pss and rsa_pss_saltlen == hLen,
// the standard TLS 1.3 configuration. Covers all 9 (RSA-2048/3072/4096 x
// SHA-256/384/512) combinations plus tampered, wrong-message, and
// Bleichenbacher-style malformed signatures. Do not edit by hand.
//
// 40 cases (18 valid, 22 invalid), 3 key groups.

#![cfg(test)]

/// SHA variant a case uses (maps to `mgf1::PssHash`).
#[derive(Clone, Copy)]
pub enum HashId {
    Sha256,
    Sha384,
    Sha512,
}

/// One RSA-PSS verification test case.
pub struct RsaPssCase {
    pub id: u32,
    /// Index into [`KEYS_SPKI_DER`].
    pub key: usize,
    pub hash: HashId,
    /// Message bytes (hex).
    pub msg: &'static str,
    /// RSA-PSS signature (hex).
    pub sig: &'static str,
    /// True iff the signature must verify.
    pub valid: bool,
}

/// SubjectPublicKeyInfo DER (hex), one per RSA key group.
pub static KEYS_SPKI_DER: &[&str] = &[
    "",
    "",
    "",
];

